import { useState, useEffect, useRef, useMemo } from "react";
import { ChatHeader } from "./components/ChatHeader";
import { ChatMessage } from "./components/ChatMessage";
import { ChatInput } from "./components/ChatInput";
import { Toast } from "./components/Toast";
import Sidebar from "./components/Sidebar";
import { ProfilePage } from "./components/ProfilePage";
import "./App.css";

function nowTime() {
  return new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}
function nowDateTime() {
  return new Date().toLocaleString([], {
    hour: "2-digit",
    minute: "2-digit",
    day: "2-digit",
    month: "2-digit",
  });
}

export default function App() {
  // --- Auth & toast ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState("");
  const [toasts, setToasts] = useState([]);

  // --- View: chat | profile ---
  const [currentView, setCurrentView] = useState("chat");

  // --- Stats (dùng cho ProfilePage) ---
  const [userStats, setUserStats] = useState({
    messagesCount: 0,
    wordsLookedUp: 0,
    daysActive: 1,
    studyHours: 2,
    streak: 3,
  });

  // --- Conversations (multi) ---
  const initialConversation = useMemo(
    () => ({
      id: crypto.randomUUID(),
      title: "New chat",
      lastUpdated: nowDateTime(),
      messages: [
        {
          id: "1",
          text: "Hello! I'm your AI assistant. How can I help you today? 💙",
          isUser: false,
          timestamp: nowTime(),
        },
      ],
    }),
    []
  );

  const [conversations, setConversations] = useState([initialConversation]);
  const [activeId, setActiveId] = useState(initialConversation.id);

  const isTyping = useRef(false); // dùng ref để không gây re-render khi đang gõ
  const [typingTick, setTypingTick] = useState(0); // tick để kích hoạt re-render cho indicator

  const activeConversation = useMemo(
    () => conversations.find((c) => c.id === activeId),
    [conversations, activeId]
  );

  const messages = activeConversation?.messages ?? [];

  const messagesEndRef = useRef(null);
  const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });

  useEffect(() => {
    scrollToBottom();
    // chỉ lắng nghe độ dài mảng để tránh thay đổi tham chiếu mảng mỗi render
  }, [messages.length, typingTick]);

  const showToast = (message, type = "success") => {
    const id = Date.now().toString();
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 3000);
  };

  // --- Helpers ---
  const updateActiveConversation = (updater) => {
    setConversations((prev) => prev.map((c) => (c.id === activeId ? updater(c) : c)));
  };

  // --- Handlers ---
  const handleSendMessage = (text) => {
    const userMsg = {
      id: Date.now().toString(),
      text,
      isUser: true,
      timestamp: nowTime(),
    };

    updateActiveConversation((c) => ({
      ...c,
      messages: [...c.messages, userMsg],
      title: c.title === "New chat" ? text.slice(0, 30) || "New chat" : c.title,
      lastUpdated: nowDateTime(),
    }));

    setUserStats((s) => ({ ...s, messagesCount: s.messagesCount + 1 }));

    // typing on
    isTyping.current = true;
    setTypingTick((t) => t + 1);

    // fake AI response
    setTimeout(() => {
      const responses = [
        "That's an interesting question! 🤔 Let me help you with that.",
        "I love helping with professional conversations! 💼 What else would you like to know?",
        "Great message! ✨ I'm here to assist you with anything you need.",
        "Thanks for sharing! 🌟 This clean interface makes chatting efficient and pleasant!",
        "I appreciate your message! 💙 How else can I help you today?",
      ];
      const aiMsg = {
        id: (Date.now() + 1).toString(),
        text: responses[Math.floor(Math.random() * responses.length)],
        isUser: false,
        timestamp: nowTime(),
      };
      updateActiveConversation((c) => ({
        ...c,
        messages: [...c.messages, aiMsg],
        lastUpdated: nowDateTime(),
      }));

      // typing off
      isTyping.current = false;
      setTypingTick((t) => t + 1);
    }, 1200);
  };

  const handleNewChat = () => {
    const convo = {
      id: crypto.randomUUID(),
      title: "New chat",
      lastUpdated: nowDateTime(),
      messages: [
        {
          id: "1",
          text: "New conversation started. How can I assist? ✨",
          isUser: false,
          timestamp: nowTime(),
        },
      ],
    };
    setConversations((prev) => [convo, ...prev]);
    setActiveId(convo.id);
    setCurrentView("chat");
  };

  const handleSelectConversation = (id) => {
    setActiveId(id);
    setCurrentView("chat");
  };

  // --- Auth actions ---
  const handleLogin = (email) => {
    setIsLoggedIn(true);
    setUserName(email.split("@")[0]);
    showToast("Successfully logged in! Welcome back! 🎉");
  };
  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserName("");
    showToast("Successfully logged out! See you soon! 👋");
  };
  const handleRegister = (email, _password, name) => {
    setIsLoggedIn(true);
    setUserName(name || email.split("@")[0]);
    showToast("Account created successfully! Welcome aboard! 🚀");
  };
  const handleWordLookup = (word) => {
    setUserStats((s) => ({ ...s, wordsLookedUp: s.wordsLookedUp + 1 }));
    showToast(`Looking up "${word}" in the dictionary! 📚`);
  };

  const handleProfileView = () => setCurrentView("profile");
  const handleBackToChat = () => setCurrentView("chat");

  return (
    <div className="app">
      <div className="layout">
        <Sidebar
          conversations={conversations}
          activeId={activeId}
          onSelect={handleSelectConversation}
          onNewChat={handleNewChat}
        />

        {currentView === "chat" ? (
          <div className="chat-main">
            <div className="chat-card">
              <ChatHeader
                title={activeConversation?.title || "AI Assistant"}
                subtitle="Always here to help"
                isLoggedIn={isLoggedIn}
                userName={userName}
                onLogin={handleLogin}
                onLogout={handleLogout}
                onRegister={handleRegister}
                onWordLookup={handleWordLookup}
                onProfileView={handleProfileView}
              />

              <div className="messages-container">
                <div className="messages-list">
                  {messages.map(m => (
                    <ChatMessage
                      key={m.id}
                      message={m.text}
                      isUser={m.isUser}
                      timestamp={m.timestamp}
                    />
                  ))}

                  {isTyping && (
                    <div className="typing-indicator">
                      <div className="typing-avatar"><span>AI</span></div>
                      <div className="typing-bubble">
                        <div className="typing-dots">
                          <div className="dot"></div><div className="dot"></div><div className="dot"></div>
                        </div>
                      </div>
                    </div>
                  )}
                  <div ref={messagesEndRef} />
                </div>
              </div>

              <ChatInput
                onSendMessage={handleSendMessage}
                disabled={isTyping}
                placeholder="Type your message..."
              />
            </div>
          </div>
        ) : (
          <ProfilePage
            userName={userName}
            userStats={userStats}
            onBackToChat={handleBackToChat}
            isLoggedIn={isLoggedIn}
          />
        )}

        {toasts.map(t => (
          <Toast key={t.id} message={t.message} type={t.type} />
        ))}
      </div>
    </div>
  );
}
